// Phase 18G — Resolve publish mode. Preserves upstream canonical envelope
// (which FF90-04 promoted). FAIL-CLOSED: missing or unknown → manual_review.
// Phase 18A contract: timeout_auto and full_auto are NEVER honored in
// Phase 18A. Future activation is a config flip, not a code change.
const up = $json;
const modeRaw = ($env.PUBLISH_MODE || 'manual_review').toString().trim().toLowerCase();
const allowed = ['manual_review', 'timeout_auto', 'full_auto'];
const mode = allowed.includes(modeRaw) ? modeRaw : 'manual_review';
return [{
  json: {
    ...up,
    publish_mode: mode,
    pipeline_stage: 'human_review',
  },
}];

// Build the human-review notification payload. The adapter writes it
// to the FF90 admin notification record; if a Telegram/email/LINE
// channel is configured, the adapter also delivers. We do NOT log
// any credentials; channel routing happens server-side.
const payload = {
  headline_th: $json.headline_th || '',
  qa_article: $json.qa_article || 'PASS',
  qa_fact: $json.qa_fact || 'HOLD',
  qa_seo: $json.qa_seo || 'PASS',
  qa_cover: $json.qa_cover || 'HOLD',
  qa_image_rights: $json.qa_image_rights || 'PASS',
  qa_wp_draft: $json.qa_wp_draft || 'PASS',
  qa_desktop: $json.qa_desktop || 'PASS',
  qa_mobile: $json.qa_mobile || 'PASS',
  wp_post_id: $json.wp_post_id || null,
  actions: ['APPROVE', 'REJECT', 'OPEN_PREVIEW'],
  publish_mode: $json.publish_mode,
};
return [{ json: { ...$json, review_payload: payload } }];

// WAIT for explicit human decision. In manual_review mode this
// is the terminal node of FF90-05. The wait is bounded only by
// a periodic re-poll — there is NO timeout auto-pass.
return [{
  json: {
    ...$('Build notification payload').item.json,
    waiting_since: new Date().toISOString(),
    waiting_until: null,
    auto_pass_after: null,
    mode_in_effect: 'manual_review',
    note: 'No timeout auto-pass in manual_review mode. The item stays at status=waiting_human_review and wp_post_status=draft indefinitely until the operator approves or rejects via /admin/editorial/[id] or an explicit /api/admin/editorial/[id]/approval call. This is enforced by the server (which rejects timeout_auto_pass when publish_mode=manual_review) and by the workflow (which has no wait-for-response timer).',
  },
}];

// Phase 18G — APPROVE branch. Preserves upstream canonical envelope.
// APPROVE marks the item ready for publish but does NOT auto-publish.
// Operator must invoke wp-publish separately (admin session).
// review_status='approved' + approval_method='manual'.
return [{
  json: {
    ...$json,
    review_status: 'approved',
    approval_method: 'manual',
    approved_at: new Date().toISOString(),
    wp_publish_called: false,
    pipeline_status: 'approved',
    pipeline_stage: 'human_review',
    note: 'Phase 18A: APPROVE marks the item ready for publish but does NOT auto-publish. Operator must invoke wp-publish separately.',
  },
}];

// No decision means pending; only explicit rejection marks the envelope rejected.
if ($json.review_decision !== 'rejected') {
  return [{ json: { ...$json, review_status: 'pending', pipeline_status: 'waiting_human_review', pipeline_stage: 'human_review' } }];
}
return [{ json: { ...$json,
  review_status: 'rejected',
  status: 'held_for_revision',
  pipeline_status: 'rejected',
  pipeline_stage: 'human_review',
  reject_reason: $json.review_reason || 'unspecified',
  rejected_at: new Date().toISOString(),
} }];

// Phase 18G — terminal promote. Re-emits canonical envelope with
// review_status. No wp-publish call. DB remains waiting_approval
// (set by FF90-04); this node only sets in-memory review_status.
const up = $json;
return [{
  json: {
    ...up,
    pipeline_stage: 'human_review',
    pipeline_status: ['approved', 'rejected'].includes(up.pipeline_status) ? up.pipeline_status : 'waiting_human_review',
    review_status: up.review_status || 'pending',
  },
}];
